# Reuse the transform function
def transform(grid):
    """Find hollow rectangles and fill interiors."""
    h = len(grid)
    w = len(grid[0])

    # Background is color 5? Need to find it dynamically
    bg_count = {}
    for row in grid:
        for val in row:
            bg_count[val] = bg_count.get(val, 0) + 1
    bg_color = max(bg_count, key=bg_count.get)

    output_grid = [row[:] for row in grid]

    # Find all non-background colors
    non_bg_colors = set()
    for row in grid:
        for val in row:
            if val != bg_color:
                non_bg_colors.add(val)

    all_rects = []

    for color in non_bg_colors:
        # Find the bounding box of all cells with this color
        cells = []
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    cells.append((r, c))

        if not cells:
            continue

        # Find bounds
        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)

        # Check if this forms a valid box (all four sides exist)
        is_valid_box = True

        # Check top row
        for c in range(min_c, max_c + 1):
            if grid[min_r][c] != color:
                is_valid_box = False
                break

        if not is_valid_box:
            continue

        # Check bottom row
        for c in range(min_c, max_c + 1):
            if grid[max_r][c] != color:
                is_valid_box = False
                break

        if not is_valid_box:
            continue

        # Check left column
        for r in range(min_r, max_r + 1):
            if grid[r][min_c] != color:
                is_valid_box = False
                break

        if not is_valid_box:
            continue

        # Check right column
        for r in range(min_r, max_r + 1):
            if grid[r][max_c] != color:
                is_valid_box = False
                break

        if not is_valid_box:
            continue

        if is_valid_box:
            all_rects.append((min_r, min_c, max_r, max_c, color))

    # Now fill interiors
    for (tr, tc, br, tc_r, color) in all_rects:
        for r in range(tr + 1, br):
            for c in range(tc + 1, tc_r):
                # Check if this cell is on the border
                if r == tr or r == br or c == tc or c == tc_r:
                    continue  # Border, leave unchanged
                # This is interior
                if color % 2 == 0:
                    output_grid[r][c] = color + 1
                else:
                    output_grid[r][c] = color - 1

    return output_grid

