def find_all_rect_boxes(grid):
    """Find all rectangular shapes where ALL 4 borders have the same color"""
    boxes = []
    changes = {}

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            color = grid[r][c]
            key = (r, c)
            if key not in changes:
                changes[key] = []
            color_list = [color]
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                        color_list.append(grid[nr][nc])

            if all(x == color for x in color_list):
                changes[key].append((-dr, -dc))  # relative position

    # Now find rectangles
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] in changes:
                relative_positions = changes[(r, c)]

                # Check if any 4 relative positions form a rectangle
                for p1 in relative_positions:
                    pr1 = r + p1[0], c + p1[1]
                    for p2 in relative_positions:
                        if p1 == p2:
